                Items = new List<SubscriptionItemOptions>
                {
                    new SubscriptionItemOptions
                    {
                        Plan = plan.Id,
                        Quantity = 1
                    }
                },
                TrialPeriod = 30, // 30 days trial period
            };

            // Create the subscription
            var subscriptionService = new StripeSubscriptionService();
            var createdSubscription = subscriptionService.Create(subscription).Result;

            // Return a success message
            return RedirectToAction("SubscriptionCreated");
        }

        [HttpGet]
        public ActionResult CreateSubscription()
        {
            // Create a new Stripe checkout session
            var checkoutSession = new StripeCheckoutSessionOptions
            {
                PaymentIntent = "payminute",
                LineItems = new List<StripeCheckoutSessionLineItemOptions>
                {
                    new StripeCheckoutSessionLineItemOptions
                    {
                        Price = "50", // $50
                        Quantity = 1
                    }
                },
                Mode = "subscription",
                TrialPeriod = 30 // 30 days trial period
            };

            // Redirect to Stripe checkout
            return Redirect(_checkoutService.CreateCheckoutSession(checkoutSession));
        }

        [HttpGet]
        public ActionResult SubscriptionCreated()
        {
            // Return a success message
            return View("SubscriptionCreated");
        }
    }
}
